import { PublicKey } from '@solana/web3.js';

const PROGRAM_ID = new PublicKey('YourProgramId11111111111111111111111111111');

export function deriveUserProfilePDA(
  userPubkey: PublicKey
): [PublicKey, number] {
  return PublicKey.findProgramAddressSync(
    [Buffer.from('profile'), userPubkey.toBuffer()],
    PROGRAM_ID
  );
}

